<?php
require_once __DIR__ . '/../app/bootstrap.php'; require_once __DIR__ . '/../app/controllers/AdminFeatureController.php';
Auth::requireLogin(); if (Auth::userRole() !== 'junkshop') { header('Location: ' . APP_URL . '/user-junkshop/dashboard.php'); exit; }
$controller = new AdminFeatureController(); $feedback = null; if ($_SERVER['REQUEST_METHOD'] === 'POST' && CSRF::verify()) $feedback = $controller->createRenewalPayment(Auth::userId(), (string) ($_POST['payment_method'] ?? ''), (string) ($_POST['payment_reference'] ?? ''));
$db = Database::getInstance(); $profile = $db->query('SELECT jp.business_name, jp.partnership_expires_at, jp.renewal_status, fc.config_value AS renewal_fee FROM junkshop_profiles jp LEFT JOIN fee_configurations fc ON fc.config_key = \'junkshop_renewal_fee\' WHERE jp.account_id = :account_id', ['account_id' => Auth::userId()])->fetch(); $payments = $db->query('SELECT payment_type, amount, payment_method, payment_status, created_at FROM junkshop_partnership_payments WHERE junkshop_account_id = :account_id ORDER BY created_at DESC', ['account_id' => Auth::userId()])->fetchAll(); $pageTitle = 'Partnership Renewal'; $currentPage = 'renewal'; $userDisplayName = Auth::userName(); ob_start();
?><div class="row g-4"><div class="col-lg-5"><div class="card border-0 shadow-sm"><div class="card-body p-4"><h2 class="fw-bold mb-1">Partnership Renewal</h2><p class="text-muted">Keep your EcoPick partnership current.</p><?php if ($feedback): ?><div class="alert alert-<?php echo $feedback['success'] ? 'success' : 'danger'; ?>"><?php echo Validator::escape($feedback['message']); ?></div><?php endif; ?><dl><dt>Partnership status</dt><dd><?php echo Validator::escape($profile['renewal_status'] ?? 'Current'); ?></dd><dt>Expiry date</dt><dd><?php echo Validator::escape($profile['partnership_expires_at'] ?: 'Not assigned'); ?></dd><dt>Renewal fee</dt><dd>₱<?php echo number_format((float) ($profile['renewal_fee'] ?? 0), 2); ?></dd></dl><form method="post"><?php echo CSRF::field(); ?><label class="form-label" for="payment_method">Payment method</label><select class="form-select mb-3" name="payment_method" id="payment_method" required><option value="">Select method</option><option>Cash</option><option>GCash</option></select><label class="form-label" for="payment_reference">Reference</label><input class="form-control mb-3" name="payment_reference" id="payment_reference" maxlength="100"><button class="btn btn-primary">Submit renewal payment</button></form></div></div></div><div class="col-lg-7"><div class="card border-0 shadow-sm"><div class="card-body p-4"><h4 class="fw-bold mb-3">Payment records</h4><div class="table-responsive"><table class="table"><thead><tr><th>Type</th><th>Amount</th><th>Method</th><th>Status</th><th>Submitted</th></tr></thead><tbody><?php foreach ($payments as $payment): ?><tr><td><?php echo Validator::escape($payment['payment_type']); ?></td><td>₱<?php echo number_format((float) $payment['amount'], 2); ?></td><td><?php echo Validator::escape($payment['payment_method'] ?: '-'); ?></td><td><?php echo Validator::escape($payment['payment_status']); ?></td><td><?php echo Validator::escape($payment['created_at']); ?></td></tr><?php endforeach; ?></tbody></table></div></div></div></div></div><?php $content = ob_get_clean(); require_once __DIR__ . '/../app/views/user_dashboard_shell.php';